func decodeCommentBlock(v vm.Value, path string) (spells.CommentBlock, error) {
	var out spells.CommentBlock
	fields, ok := v.MapView()
	if !ok {
		return out, mismatch(path, "CommentBlock", v)
	}
	for _, key := range fields.MapKeys() {
		item, _ := fields.MapGet(key)
		switch key {
		case "open":
			sOpen, err := decodeStr(item, path+".open")
			if err != nil {
				return out, err
			}
			out.Open = sOpen
		case "close":
			sClose, err := decodeStr(item, path+".close")
			if err != nil {
				return out, err
			}
			out.Close = sClose
		default:
			return out, unknownMember(path, "CommentBlock", key)
		}
	}
	return out, nil
}

